css:
.tg { display: grid; gap: 1.6rem 3rem; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); margin: 0; }
.tg__p { margin: 0; }
.tg__img { width: 100%; max-width: 22rem; height: 640px; border-radius: 14px; overflow: hidden; margin-bottom: 1.1rem; background: var(--bff-sunken, #dad7be); }
.tg__img picture, .tg__img img, .tg__img .os-img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: 50% 30%; }
.tg__n { margin: 0 0 .2rem; font-size: clamp(1.45rem, 1.1rem + 1.2vw, 2rem); line-height: 1.15; letter-spacing: -.015em; }
.tg__r { margin: 0; color: var(--os-color-text-muted); max-width: 62ch; }
